import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Private Data","description":"","frontmatter":{"title":"Private Data"},"headers":[],"relativePath":"docs/privacy-and-security/private-data.md","filePath":"docs/privacy-and-security/private-data.md","lastUpdated":1794014279000}'),s={name:"docs/privacy-and-security/private-data.md"};function i(n,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="private-data" tabindex="-1">Private Data <a class="header-anchor" href="#private-data" aria-label="Permalink to &quot;Private Data&quot;">​</a></h1><p>OrbySystems&#39;s goal is to protect all of your private data. It does that primarily by never letting any of your data (private or not) leave the machine. It also avoids storing your private data when it can. When data does need to leave the local machine, OrbySystems provides safeguards to avoid leaking your private data.</p><h2 id="pii" tabindex="-1">PII <a class="header-anchor" href="#pii" aria-label="Permalink to &quot;PII&quot;">​</a></h2><p>PII (personally identifiable information) is defined as anything that may identify you as an individual: your name, home address, phone number, etc. In the official definition, more sensitive data like account numbers, passwords, etc are typically not PII, they are in a higher sensitivity category like <strong>secrets</strong> or <strong>confidential data</strong>. For OrbySystems, we use PII in the general sense of any data you want to keep private, regardless of how sensitive it is.</p><h2 id="data-storage" tabindex="-1">Data Storage <a class="header-anchor" href="#data-storage" aria-label="Permalink to &quot;Data Storage&quot;">​</a></h2><h3 id="finance-data-ingest" tabindex="-1">Finance data ingest <a class="header-anchor" href="#finance-data-ingest" aria-label="Permalink to &quot;Finance data ingest&quot;">​</a></h3><p>Finance statement ingest does not store your original statements, it only stores the derived information. For finance, these are your transactions: dates, amounts, descriptions, etc. Additionally, all account numbers are masked to their last 4 digits. It does remember where your original document was on disk so it can refer you it if needed.</p><h3 id="general-document-ingest" tabindex="-1">General document ingest <a class="header-anchor" href="#general-document-ingest" aria-label="Permalink to &quot;General document ingest&quot;">​</a></h3><p>General documents are split into parts, vectorized, and stored in a vector database. This is referred to as RAG (retrieval-augmented generation). As such, all original data is preserved in our database.</p><h2 id="data-egress" tabindex="-1">Data Egress <a class="header-anchor" href="#data-egress" aria-label="Permalink to &quot;Data Egress&quot;">​</a></h2><p>There are a couple of points where data can leave the machine, and these are tracked explicitly in Settings → Privacy. See <a href="/docs/settings/privacy">Privacy settings</a>.</p><ul><li><strong>Web search</strong>: The queries to web search are checked by the PII detector</li><li><strong>Browser tool</strong>: Navigation URLs for the local browser are checked by the PII detector, otherwise the browser tool never sends data - it is read-only</li><li><strong>Sandbox</strong>: The LLM can run python scripts in the sandbox with whitelisted network access, see <a href="./sandboxing">Sandboxing</a>.</li><li><strong>Cloud models</strong>: If you choose a chat model that runs somewhere else, it receives every message and what it reads to answer. See <a href="./trusted-vs-untrusted-models">Models and your data</a>.</li></ul><p>For runtime cases like web search and browser tool, if OrbySystems detects PII, it will ask you for approval before allowing the action to proceed.</p><h2 id="redacting-and-detecting-pii-yourself" tabindex="-1">Redacting and detecting PII yourself <a class="header-anchor" href="#redacting-and-detecting-pii-yourself" aria-label="Permalink to &quot;Redacting and detecting PII yourself&quot;">​</a></h2><p>If you want to share or save a document (like a sample statement) without exposing personal information, use the standalone <a href="/docs/tools/pii-redactor">PII Redactor</a> tool to strip it out.</p><p>Settings → Privacy uses this same detection automatically in the background — see <a href="/docs/settings/privacy">Privacy settings</a>.</p><h2 id="pii-and-cloud-models" tabindex="-1">PII and cloud models <a class="header-anchor" href="#pii-and-cloud-models" aria-label="Permalink to &quot;PII and cloud models&quot;">​</a></h2><p>Web search queries and browser addresses are checked for personal information before they&#39;re sent. A chat model is different: it reads your data to answer you. The OrbySystems models do that on your computer; a cloud model does it on its provider&#39;s servers, so choose one only if you trust where it runs. See <a href="/docs/privacy-and-security/trusted-vs-untrusted-models">Models and your data</a>.</p>',18)])])}const y=a(s,[["render",i]]);export{p as __pageData,y as default};
